let DateAgoPipe = class DateAgoPipe {
    transform(value, args) {
        if (value) {
            const seconds = Math.floor((+new Date() - +new Date(value)) / 1000);
            if (seconds < 49) // less than 30 seconds ago will show as 'Just now'
                return 'Justo ahora';
            const intervals = {
                'año': 31536000,
                'mes': 2592000,
                'semana': 604800,
                'dia': 86400,
                'hora': 3600,
                'minuto': 60,
                'segundo': 1
            };
            let counter;
            for (const interval_key in intervals) {
                counter = Math.floor(seconds / intervals[interval_key]);
                if (counter > 0)
                    if (counter === 1) {
                        return 'Hace ' + counter + ' ' + interval_key; // singular (1 day ago)
                    }
                    else {
                        let plural = interval_key === 'mes' ? 'es' : 's';
                        return 'Hace ' + counter + ' ' + interval_key + plural; // plural (2 days ago)
                    }
            }
        }
        return value;
    }
};
